public class Employee{private int employeeId;private String name,department,designation;private double basicSalary;public Employee(int id,String n,String d,String des,double s){employeeId=id;name=n;department=d;designation=des;basicSalary=s;}public int getEmployeeId(){return employeeId;}public String getName(){return name;}public String getDepartment(){return department;}public String getDesignation(){return designation;}public double getBasicSalary(){return basicSalary;}}